1	/**
2	 * job-timeouts.test.ts — no generated job is bounded only by GitHub's default.
3	 *
4	 * A job that declares no `timeout-minutes` runs under a **six-hour** default. A
5	 * step that then hangs — a network call with no timeout, a script waiting on
6	 * something that never answers — holds that job, and everything queued behind it,
7	 * for six hours. For the jobs that decide what happens next (the post-merge
8	 * re-invocation, the aggregation that starts the parent, the trigger after a
9	 * sub-issue closes) the hang costs the same as a wrong answer: a continuation that
10	 * never arrives, with nothing saying so until the default finally fires.
11	 *
12	 * `atomaton-pr-closed`, `atomaton-sub-issue-closed`, `atomaton-entry` and
13	 * `atomaton-manual-comment` shipped that way — eleven of their thirteen jobs
14	 * (#237). The missing
15	 * value was never a deliberate budget; it was nobody having said one, because the
16	 * job file that would have carried the default is the one place the question never
17	 * comes up.
18	 *
19	 * ## Why this is two tests
20	 *
21	 * A job is bounded in one of two places, and it depends on its shape:
22	 *
23	 * - a `runs-on:` job carries `timeout-minutes` itself (`SCRIPT_JOB_TIMEOUT_MINUTES`
24	 *   for the ones that are one script long, a considered value for the rest)
25	 * - a job that calls a reusable workflow (`uses: ./.github/workflows/x.yml`)
26	 *   **cannot** carry one — GitHub rejects the key — so its bound is the callee's,
27	 *   and the callee has to have declared it
28	 *
29	 * Checking only the first shape would let the second shape's bound go missing
30	 * silently: the callee's own timeout is the whole reason `entry.run` and
31	 * `manual-comment.run` are allowed to be unbounded here.
32	 */
33	import { describe, expect, test } from "bun:test";
34	import { readdirSync, readFileSync } from "node:fs";
35	
36	interface Job {
37	  "timeout-minutes"?: number;
38	  uses?: string;
39	}
40	
41	const WORKFLOWS = "dist/.github/workflows";
42	
43	function jobsOf(file: string): [string, Job][] {
44	  const workflow = Bun.YAML.parse(readFileSync(`${WORKFLOWS}/${file}`, "utf8")) as {
45	    jobs?: Record<string, Job>;
46	  };
47	  return Object.entries(workflow.jobs ?? {});
48	}
49	
50	function generatedWorkflows(): string[] {
51	  return readdirSync(WORKFLOWS)
52	    .filter((name) => name.endsWith(".yml"))
53	    .sort();
54	}
55	
56	describe("generated jobs", () => {
57	  test("each one is bounded, by itself or by the workflow it calls", () => {
58	    const all = generatedWorkflows().flatMap((file) =>
59	      jobsOf(file).map(([name, job]) => ({ file, name, job })),
60	    );
61	    expect(all.length).toBeGreaterThan(0);
62	
63	    const unbounded = all
64	      .filter(({ job }) => job["timeout-minutes"] === undefined && job.uses === undefined)
65	      .map(({ file, name }) => `${file}: ${name}`);
66	
67	    expect(unbounded, "bounded only by GitHub's six-hour default").toEqual([]);
68	  });
69	
70	  test("a job that calls a reusable workflow finds the bound there", () => {
71	    const callers = generatedWorkflows().flatMap((file) =>
72	      jobsOf(file)
73	        .filter(([, job]) => job.uses !== undefined)
74	        .map(([name, job]) => ({ file, name, uses: job.uses as string })),
75	    );
76	
77	    for (const { file, name, uses } of callers) {
78	      // `owner/repo/.github/workflows/x.yml@ref` and `./.github/workflows/x.yml`
79	      // both end in the callee's filename.
80	      const callee = uses.slice(uses.lastIndexOf("/") + 1);
81	      expect(generatedWorkflows(), `${file}: ${name} calls a workflow nothing generates`).toContain(callee);
82	
83	      const bounded = jobsOf(callee).every(([, job]) => job["timeout-minutes"] !== undefined);
84	      expect(bounded, `${file}: ${name} is only bounded by GitHub's default`).toBe(true);
85	    }
86	  });
87	});

